"""Deterministic two-phase min-cost flow for building-v2 (fork of flow_solver.py; v1 is untouched).

Differences from v1: multi-origin injection, bidirectional doors, per-element multipliers, entry-only closures
(no inbound arcs after a time, outbound arcs kept until a zone is untenable) and nested per-zone/per-exit timeline
frames. Counts are modeled crossings inside a declared model, never survival.
"""
from __future__ import annotations

import hashlib
import json
import math
import time
from dataclasses import dataclass
from typing import Any, Dict, List, Optional, Tuple
from uuid import uuid4

try:  # the sandbox image has no networkx; solve() needs it, estimate.py does not
    import networkx as nx
except ImportError:  # pragma: no cover
    nx = None

from .checker_v2 import (
    EXIT_COLLECTOR,
    SOURCE,
    UNASSIGNED,
    ClaimedResult,
    SolveInputs,
    check,
    validate_inputs,
)
from .model import VenueV2


HAZARD_WAIT_WEIGHT = 10


@dataclass
class SolveOutcome:
    run_id: str
    candidate_hash: str
    status: str
    initial_population: int
    completed_crossings: int
    remaining_population: int
    horizon_seconds: int
    time_step_seconds: int
    exit_breakdown: Dict[str, int]
    zone_remaining: Dict[str, int]
    timeline: List[Dict[str, Any]]
    validator_report: Dict[str, Any]
    witness: Dict[Any, Dict[Any, int]]
    inputs: SolveInputs
    timings_ms: float


def _floor(x: float) -> int:
    return int(math.floor(x + 1e-9))


def _ceil(x: float) -> int:
    return int(math.ceil(x - 1e-9))


class FlowSolverV2:
    def __init__(self, venue: VenueV2):
        self.venue = venue

    def candidate_hash(self, inputs: SolveInputs, horizon: int, dt: int) -> str:
        payload = [self.venue.geometry_revision, inputs.canonical(), horizon, dt]
        return hashlib.sha256(json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()[:16]

    def solve(self, inputs: Optional[SolveInputs] = None, horizon_seconds: Optional[int] = None,
              time_step_seconds: Optional[int] = None) -> SolveOutcome:
        started = time.perf_counter()
        venue = self.venue
        inputs = inputs or SolveInputs()
        H = horizon_seconds or venue.default_horizon_seconds
        dt = time_step_seconds or venue.time_step_seconds
        if H % dt or H <= 0:
            raise ValueError(f"Horizon must be a positive multiple of the {dt}s step")
        validate_inputs(venue, inputs, H, dt)
        T = H // dt
        N = sum(z.initial_occupants for z in venue.zones)

        G = nx.DiGraph()
        for zone in venue.zones:
            if zone.initial_occupants > 0:
                G.add_edge(SOURCE, (zone.id, 0), capacity=zone.initial_occupants, weight=0)
        # Among plans with the same number of crossings, prefer ones that do not leave people waiting inside
        # a zone that is closed to entry or becomes untenable (lower modeled exposure).
        hazard_zones = set(inputs.no_entry_from) | set(inputs.untenable_at)
        for zone in venue.zones:
            wait_cost = HAZARD_WAIT_WEIGHT if zone.id in hazard_zones else 1
            for t in range(T):
                G.add_edge((zone.id, t), (zone.id, t + 1), capacity=zone.max_capacity, weight=wait_cost)

        def departures_end(zone_id: str) -> int:
            return inputs.untenable_at[zone_id] // dt if zone_id in inputs.untenable_at else T + 1

        for door in venue.doors:
            if door.id in inputs.closed_doors:
                continue
            thr, trv = inputs.multipliers.get(door.id, (1.0, 1.0))
            steps = max(1, _ceil(door.travel_time_seconds * trv / dt))
            slot = max(1, _floor(door.throughput_per_sec * dt * thr))
            for origin, dest in ((door.zones[0], door.zones[1]), (door.zones[1], door.zones[0])):
                last = min(T - steps + 1, departures_end(origin))
                if dest in inputs.no_entry_from:
                    last = min(last, inputs.no_entry_from[dest] // dt)
                for t in range(max(0, last)):
                    # a hop costs its travel steps plus one, so wandering is never cheaper than waiting
                    G.add_edge((origin, t), (dest, t + steps), capacity=slot, weight=steps + 1)

        service_nodes: Dict[str, List[Tuple[Any, str]]] = {e.id: [] for e in venue.exits}
        for ex in venue.exits:
            thr, _ = inputs.multipliers.get(ex.id, (1.0, 1.0))
            slot = max(1, _floor(ex.service_rate_per_sec * dt * thr))
            last = min(T + 1, departures_end(ex.zone))
            if ex.id in inputs.exit_closed_from:
                last = min(last, inputs.exit_closed_from[ex.id] // dt)
            for t in range(max(0, last)):
                node = f"X_{ex.id}_{t}"
                G.add_edge((ex.zone, t), node, capacity=slot, weight=0)
                G.add_edge(node, EXIT_COLLECTOR, capacity=slot, weight=0)
                service_nodes[ex.id].append(((ex.zone, t), node))

        for zone in venue.zones:
            G.add_edge((zone.id, T), UNASSIGNED, capacity=zone.max_capacity, weight=0)
        for node in (SOURCE, EXIT_COLLECTOR, UNASSIGNED):
            G.add_node(node)

        # Phase 1: maximise completed crossings.
        sink = "SINK"
        G.add_edge(EXIT_COLLECTOR, sink, capacity=N, weight=-1000)
        G.add_edge(UNASSIGNED, sink, capacity=N, weight=0)
        G.nodes[SOURCE]["demand"] = -N
        G.nodes[sink]["demand"] = N
        infeasible = False
        try:
            completed = nx.min_cost_flow(G)[EXIT_COLLECTOR][sink]
        except nx.NetworkXUnfeasible:
            infeasible = True
            completed = 0
        G.remove_node(sink)

        # Phase 2: cheapest schedule at exactly that count.
        remaining = N - completed
        G.nodes[SOURCE]["demand"] = -N
        G.nodes[EXIT_COLLECTOR]["demand"] = completed
        G.nodes[UNASSIGNED]["demand"] = remaining
        flow: Dict[Any, Dict[Any, int]] = {}
        if not infeasible:
            try:
                flow = nx.min_cost_flow(G)
            except nx.NetworkXUnfeasible:
                flow = {}

        exit_breakdown = {e.id: 0 for e in venue.exits}
        for ex_id, pairs in service_nodes.items():
            for origin, node in pairs:
                exit_breakdown[ex_id] += flow.get(origin, {}).get(node, 0)
        zone_remaining = {z.id: flow.get((z.id, T), {}).get(UNASSIGNED, 0) for z in venue.zones}
        timeline = self._timeline(flow, T, dt)

        if infeasible:
            status = "SOLVER_INFEASIBLE"
        elif completed == N:
            status = "COMPLETE_WITHIN_MODEL"
        elif completed > 0:
            status = "PARTIAL_WITHIN_HORIZON"
        else:
            status = "NO_FEASIBLE_EXIT"

        report = check(venue, inputs, H, dt, ClaimedResult(
            initial_population=N, completed_crossings=completed, remaining_population=remaining,
            exit_breakdown=exit_breakdown, zone_remaining=zone_remaining, status=status,
            timeline=timeline, witness=flow))
        return SolveOutcome(
            run_id=f"run-{uuid4().hex}", candidate_hash=self.candidate_hash(inputs, H, dt), status=status,
            initial_population=N, completed_crossings=completed, remaining_population=remaining,
            horizon_seconds=H, time_step_seconds=dt, exit_breakdown=exit_breakdown, zone_remaining=zone_remaining,
            timeline=timeline, validator_report=report, witness=flow, inputs=inputs,
            timings_ms=round((time.perf_counter() - started) * 1000.0, 2))

    def _timeline(self, flow: Dict[Any, Dict[Any, int]], T: int, dt: int) -> List[Dict[str, Any]]:
        """Frames sampled after arrivals and exit service, before departures (same convention as v1)."""
        venue = self.venue
        incoming: Dict[Any, int] = {}
        transit_arcs: List[Tuple[int, int, int]] = []
        for u, dests in flow.items():
            for v, amount in dests.items():
                if not amount:
                    continue
                incoming[v] = incoming.get(v, 0) + amount
                if isinstance(u, tuple) and isinstance(v, tuple) and u[0] != v[0]:
                    transit_arcs.append((u[1], v[1], amount))
        cumulative = {e.id: 0 for e in venue.exits}
        frames: List[Dict[str, Any]] = []
        for t in range(T + 1):
            for e in venue.exits:
                cumulative[e.id] += flow.get((e.zone, t), {}).get(f"X_{e.id}_{t}", 0)
            occupancy: Dict[str, int] = {}
            for z in venue.zones:
                served = sum(flow.get((z.id, t), {}).get(f"X_{e.id}_{t}", 0) for e in venue.exits if e.zone == z.id)
                occupancy[z.id] = incoming.get((z.id, t), 0) - served
            in_transit = sum(a for dep, arr, a in transit_arcs if dep < t < arr)
            frames.append({
                "step": t,
                "time_seconds": t * dt,
                "occupancy": occupancy,
                "exits_cumulative": dict(cumulative),
                "in_transit": in_transit,
                "total_completed": sum(cumulative.values()),
            })
        return frames
